CREATE TABLE IF NOT EXISTS hw_devices(id VARCHAR(80) PRIMARY KEY,installation_id CHAR(32) NOT NULL UNIQUE,model VARCHAR(60) NOT NULL,firmware VARCHAR(40) NOT NULL,token_hash CHAR(64) NOT NULL,pair_code CHAR(8) NULL,pair_expires_at DATETIME(3) NULL,user_id VARCHAR(80) NULL,name VARCHAR(80) NOT NULL,caps JSON NOT NULL,status ENUM('pending','bound','revoked') NOT NULL DEFAULT 'pending',last_seen_at DATETIME(3) NULL,last_ip VARCHAR(64) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),UNIQUE KEY hw_devices_pair_code(pair_code),INDEX hw_devices_user(user_id,status),INDEX hw_devices_token(token_hash),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS hw_sessions(id VARCHAR(80) PRIMARY KEY,device_id VARCHAR(80) NOT NULL,user_id VARCHAR(80) NOT NULL,game_session_id VARCHAR(80) NULL,last_frame_rev INT NOT NULL DEFAULT 0,input_count INT NOT NULL DEFAULT 0,attached_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),closed_at DATETIME(3) NULL,INDEX hw_sessions_device(device_id,closed_at),INDEX hw_sessions_game(game_session_id),FOREIGN KEY(device_id) REFERENCES hw_devices(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS hw_events(id VARCHAR(80) PRIMARY KEY,device_id VARCHAR(80) NOT NULL,kind VARCHAR(24) NOT NULL,payload JSON NOT NULL,accepted BOOLEAN NOT NULL,message VARCHAR(300) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX hw_events_device(device_id,created_at),INDEX hw_events_kind(kind,created_at),FOREIGN KEY(device_id) REFERENCES hw_devices(id));
